Definition mk_1RB1RA_1LC0RA_0RB1LD_0LB0LD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1RA_1LC0RA_0RB1LD_0LB0LD.

(** 1RB1RA_1LC0RA_0RB1LD_0LB0LD *)
(** 1RB1RA_1LC0RA_0RB1LD_0LB0LD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1RA_1LC0RA_0RB1LD_0LB0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DR StA
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StA
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S0 DL StD end.

(** Its mirror 1LB1LA_1RC0LA_0LB1RD_0RB0RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1RA_1LC0RA_0RB1LD_0LB0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DL StA
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DR StB | StD, S1 => mk S0 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RA_1LC0RA_0RB1LD_0LB0LD : list Instr := [].
Definition tmw_1RB1RA_1LC0RA_0RB1LD_0LB0LD : TM := tm_wrap_trs tmm_1RB1RA_1LC0RA_0RB1LD_0LB0LD pins_1RB1RA_1LC0RA_0RB1LD_0LB0LD.
Local Notation tm := tmw_1RB1RA_1LC0RA_0RB1LD_0LB0LD.

Lemma mirror_ok_1RB1RA_1LC0RA_0RB1LD_0LB0LD : mirror_tm tm_1RB1RA_1LC0RA_0RB1LD_0LB0LD = tmm_1RB1RA_1LC0RA_0RB1LD_0LB0LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

