Lemma geo_1RB1RA_1LC0RD_0RA0LC_1LD1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RA_1LC0RD_0RA0LC_1LD1RA) = lift (Cc (Pos.succ p)).
