    exact (srun_sound tm true true chb_1RB1RA_1LC0RD_0RA1LB_0LB1RD B0_1RB1RA_1LC0RD_0RA1LB_0LB1RD BB1_1RB1RA_1LC0RD_0RA1LB_0LB1RD 4 8
             run_boot_1RB1RA_1LC0RD_0RA1LB_0LB1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 8), (cden [] [] j B1_1RB1RA_1LC0RD_0RA1LB_0LB1RD).
