  apply (vis_via_fill tm Cc Cin lapin_1RB1RA_1LC0RD_0RA1LB_0LB1RD q p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1RA_1LC0RD_0RA1LB_0LB1RD). split;
      [| exact (gbo_1RB1RA_1LC0RD_0RA1LB_0LB1RD j)].
