(** ** The lap *)

Lemma lap_1RB1RA_1LC0RD_0RA1LB_0LB1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
