  - destruct (lapi_1RB1RA_1LC0RD_0RA1LB_0LB1RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1RA_1LC0RD_0RA1LB_0LB1RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RA_1LC0RD_0RA1LB_0LB1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
