  exists (8 * j + 4), (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j A1_1RB1RA_1LC1LA_0LC0LD_0RA0RC).
  split; [lia|]. split; [| exact (gei_1RB1RA_1LC1LA_0LC0LD_0RA0RC p j q0 E)].
  rewrite (gsi_1RB1RA_1LC1LA_0LC0LD_0RA0RC p j q0 E).
  exact (srun_sound tm false true chi_1RB1RA_1LC1LA_0LC0LD_0RA0RC A0_1RB1RA_1LC1LA_0LC0LD_0RA0RC A1_1RB1RA_1LC1LA_0LC0LD_0RA0RC 8 4
           run_int_1RB1RA_1LC1LA_0LC0LD_0RA0RC (Ap_Alph_00_10_1 q0 ++ [S0]) [] j
