Lemma geo_1RB1RA_1LC1LA_0LC0LD_0RA0RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RA_1LC1LA_0LC0LD_0RA0RC) = lift (Cc (Pos.succ p)).
