(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1RA_1LC1LA_0RD0LC_1LB0RA : sconf := mkC StD (mkS [] [S0;S0] 1 0 [S0;S1;S1;S0]) S0 (mkS [S0;S0] [] 0 0 []).
Definition chb_1RB1RA_1LC1LA_0RD0LC_1LB0RA : list lstep := [SWinR 4; SCycL 4 0; SWin 4; SCycR 2; SWin 2].

Lemma run_boot_1RB1RA_1LC1LA_0RD0LC_1LB0RA : srun tm true true chb_1RB1RA_1LC1LA_0RD0LC_1LB0RA B0_1RB1RA_1LC1LA_0RD0LC_1LB0RA = Some (BB1_1RB1RA_1LC1LA_0RD0LC_1LB0RA, 6, 10).
