(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RA_1LC1LA_0RD0LC_1LB0RA : sconf := mkC StD (mkS [] [S0;S1] 1 0 [S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1RA_1LC1LA_0RD0LC_1LB0RA : list lstep := [SWinR 4; SCycL 4 0; SWin 5; SWinL 7; SCycR 2; SWin 2; SRotL 2; SFoldL 1].

Lemma run_exit_1RB1RA_1LC1LA_0RD0LC_1LB0RA : srun tm true true che_1RB1RA_1LC1LA_0RD0LC_1LB0RA BE0_1RB1RA_1LC1LA_0RD0LC_1LB0RA = Some (B1_1RB1RA_1LC1LA_0RD0LC_1LB0RA, 6, 18).
