Lemma lapin_1RB1RA_1LC1LA_0RD0LC_1LB0RA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 10), (cden (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i AI1_1RB1RA_1LC1LA_0RD0LC_1LB0RA).
  split; [lia|]. split; [| exact (gen_1RB1RA_1LC1LA_0RD0LC_1LB0RA v i q0 E)].
