  exact (srun_sound tm false true chn_1RB1RA_1LC1LA_0RD0LC_1LB0RA AI0_1RB1RA_1LC1LA_0RD0LC_1LB0RA AI1_1RB1RA_1LC1LA_0RD0LC_1LB0RA 6 10
           run_inner_1RB1RA_1LC1LA_0RD0LC_1LB0RA (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
