Lemma gsi_1RB1RA_1LC1RA_0RD0LC_1LB0RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j A0_1RB1RA_1LC1RA_0RD0LC_1LB0RA.
