  split; [lia|]. split; [| exact (gei_1RB1RA_1LC1RA_0RD0LC_1LB0RB p j q0 E)].
  rewrite (gsi_1RB1RA_1LC1RA_0RD0LC_1LB0RB p j q0 E).
  exact (srun_sound tm false true chi_1RB1RA_1LC1RA_0RD0LC_1LB0RB A0_1RB1RA_1LC1RA_0RD0LC_1LB0RB A1_1RB1RA_1LC1RA_0RD0LC_1LB0RB 4 10
           run_int_1RB1RA_1LC1RA_0RD0LC_1LB0RB (Ap_Alph_00_01_1 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
