Lemma geo_1RB1RA_1LC1RA_0RD0LC_1LB0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RA_1LC1RA_0RD0LC_1LB0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_00_01_1.cview_none_Alph_00_01_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RA_1LC1RA_0RD0LC_1LB0RB
             = (StD, (rep [S0;S0] (S j) ++ [S1], S0, (([]) ++ [S0]) ++ [S0]))).
  { unfold cden, B1_1RB1RA_1LC1RA_0RD0LC_1LB0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S0;S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1RA_1LC1RA_0RD0LC_1LB0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
