  exact (srun_sound tm false true chn_1RB1RA_1LC1RA_0RD0LC_1LC1RA AI0_1RB1RA_1LC1RA_0RD0LC_1LC1RA AI1_1RB1RA_1LC1RA_0RD0LC_1LC1RA 4 8
           run_inner_1RB1RA_1LC1RA_0RD0LC_1LC1RA (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
