  split; [lia|]. split; [| exact (gen_1RB1RA_1LC1RA_1RA0LD_0RC0LD v i q0 E)].
  rewrite (gsn_1RB1RA_1LC1RA_1RA0LD_0RC0LD v i q0 E).
  exact (srun_sound tm false true chn_1RB1RA_1LC1RA_1RA0LD_0RC0LD AI0_1RB1RA_1LC1RA_1RA0LD_0RC0LD AI1_1RB1RA_1LC1RA_1RA0LD_0RC0LD 4 6
           run_inner_1RB1RA_1LC1RA_1RA0LD_0RC0LD (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
