(** ** The lap *)

Lemma lap_1RB1RA_1LC1RA_1RA0LD_0RC0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
