  - destruct (lapi_1RB1RA_1LC1RA_1RA0LD_0RC0LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1RA_1LC1RA_1RA0LD_0RC0LD p j' E).
