(** ** Bootstrap *)

Lemma boot_1RB1RA_1LC1RA_1RA0LD_0RC0LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 12.
  assert (H : match csteps tm 12 c0 with
