Lemma fireo_1RB1RA_1LC1RA_1RA0LD_0RC0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RA_1LC1RA_1RA0LD_0RC0LD = Some t ->
