Lemma gei_1RB1RA_1LC1RA_1RD0LC_1LD0RB : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_00_01_1 q0 ++ [S0]) [] j A1_1RB1RA_1LC1RA_1RD0LC_1LD0RB = Cc (Pos.succ p).
Proof.
