(** ** The lap *)

Lemma lap_1RB1RA_1LC1RA_1RD0LC_1LD0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
