    apply (lap_of_run tm Cc true true cho_1RB1RA_1LC1RA_1RD0LC_1LD0RB B0_1RB1RA_1LC1RA_1RD0LC_1LD0RB B1_1RB1RA_1LC1RA_1RD0LC_1LD0RB 4 10 p j' [] []).
    + exact run_ovf_1RB1RA_1LC1RA_1RD0LC_1LD0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RA_1LC1RA_1RD0LC_1LD0RB p j' E).
    + exact (geo_1RB1RA_1LC1RA_1RD0LC_1LD0RB p j' E).
