    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RA_1LC1RA_1RD0LC_1LD0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RA_1LC1RA_1RD0LC_1LD0RB = Some t ->
