  apply (fire_of_run_instr tm Cc true true l B0_1RB1RA_1LC1RA_1RD0LC_1LD0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RA_1LC1RA_1RD0LC_1LD0RB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RA_1LC1RA_1RD0LC_1LD0RB : forall t, ~ In t pins_1RB1RA_1LC1RA_1RD0LC_1LD0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RA_1LC1RA_1RD0LC_1LD0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1RA_1LC1RA_1RD0LC_1LD0RB
      with (l := [SWin 2; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RA_1LC1RA_1RD0LC_1LD0RB
      with (l := [SWin 2; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RA_1LC1RA_1RD0LC_1LD0RB
      with (l := [SWin 2; SCycL 2 0; SWin 2; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RA_1LC1RA_1RD0LC_1LD0RB
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RA_1LC1RA_1RD0LC_1LD0RB
      with (l := [SWin 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RA_1LC1RA_1RD0LC_1LD0RB
      with (l := [SWin 2; SCycL 2 0; SWin 2; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RA_1LC1RA_1RD0LC_1LD0RB
