Lemma gsi_1RB1RA_1LC1RB_0RA1LD_1LC0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_01_11_011 q0 ++ [S0]) [] j A0_1RB1RA_1LC1RB_0RA1LD_1LC0LC.
