  split; [lia|]. split; [| exact (gen_1RB1RA_1LC1RB_0RA1LD_1LC0LC v i q0 E)].
  rewrite (gsn_1RB1RA_1LC1RB_0RA1LD_1LC0LC v i q0 E).
  exact (srun_sound tm false true chn_1RB1RA_1LC1RB_0RA1LD_1LC0LC AI0_1RB1RA_1LC1RB_0RA1LD_1LC0LC AI1_1RB1RA_1LC1RB_0RA1LD_1LC0LC 4 16
           run_inner_1RB1RA_1LC1RB_0RA1LD_1LC0LC (Ip q0 ++ [S1;S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
