  exact (srun_sound tm false true chi_1RB1RA_1LC1RB_0RA1LD_1RA0LC A0_1RB1RA_1LC1RB_0RA1LD_1RA0LC A1_1RB1RA_1LC1RB_0RA1LD_1RA0LC 4 16
           run_int_1RB1RA_1LC1RB_0RA1LD_1RA0LC (Ap_Alph_01_11_011 q0 ++ [S0]) [] j
