Definition pins_1RB1RA_1LC1RB_0RB1LD_0RA0LC : list Instr := [].
Definition tmw_1RB1RA_1LC1RB_0RB1LD_0RA0LC : TM := tm_wrap_trs tmm_1RB1RA_1LC1RB_0RB1LD_0RA0LC pins_1RB1RA_1LC1RB_0RB1LD_0RA0LC.
