Lemma gz_1RB1RA_1LC1RB_0RD0LC_1LB0RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB1RA_1LC1RB_0RD0LC_1LB0RA /\
