  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RA_1LC1RD_0RB0LC_0LA1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RA_1LC1RD_0RB0LC_0LA1LA p j E)].
