Definition mk_1RB1RA_1LC1RD_0RB0LC_0LA1RA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1RA_1LC1RD_0RB0LC_0LA1RA.

(** 1RB1RA_1LC1RD_0RB0LC_0LA1RA *)
(** 1RB1RA_1LC1RD_0RB0LC_0LA1RA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1RA_1LC1RD_0RB0LC_0LA1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DR StA
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S0 DL StC
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DR StA end.

(** Its mirror 1LB1LA_1RC1LD_0LB0RC_0RA1LA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1RA_1LC1RD_0RB0LC_0LA1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S1 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RA_1LC1RD_0RB0LC_0LA1RA : list Instr := [].
Definition tmw_1RB1RA_1LC1RD_0RB0LC_0LA1RA : TM := tm_wrap_trs tmm_1RB1RA_1LC1RD_0RB0LC_0LA1RA pins_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
Local Notation tm := tmw_1RB1RA_1LC1RD_0RB0LC_0LA1RA.

Lemma mirror_ok_1RB1RA_1LC1RD_0RB0LC_0LA1RA : mirror_tm tm_1RB1RA_1LC1RD_0RB0LC_0LA1RA = tmm_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1RA_1LC1RD_0RB0LC_0LA1RA (p : positive) : cconf := (StB, (Ap_Alph_00_01_1 p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1RA_1LC1RD_0RB0LC_0LA1RA.

(** ** The certificate *)

Definition A0_1RB1RA_1LC1RD_0RB0LC_0LA1RA : sconf := mkC StB (mkS [] [S0;S1] 1 0 [S0;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1RA_1LC1RD_0RB0LC_0LA1RA : sconf := mkC StB (mkS [] [S0;S0] 1 0 [S0;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chi_1RB1RA_1LC1RD_0RB0LC_0LA1RA : list lstep := [SWinR 2; SCycL 4 0; SWin 6; SCycR 2; SWin 2].

Lemma run_int_1RB1RA_1LC1RD_0RB0LC_0LA1RA : srun tm false true chi_1RB1RA_1LC1RD_0RB0LC_0LA1RA A0_1RB1RA_1LC1RD_0RB0LC_0LA1RA = Some (A1_1RB1RA_1LC1RD_0RB0LC_0LA1RA, 6, 10).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1RA_1LC1RD_0RB0LC_0LA1RA : sconf := mkC StB (mkS [] [S0;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1RA_1LC1RD_0RB0LC_0LA1RA : sconf := mkC StB (mkS [] [S0;S0] 1 1 [S1]) S0 (mkS [S0] [] 0 0 []).
Definition cho_1RB1RA_1LC1RD_0RB0LC_0LA1RA : list lstep := [SWinR 2; SCycL 4 0; SWin 2; SWinL 4; SCycR 2; SWin 2; SRotL 2; SFoldL 1].

Lemma run_ovf_1RB1RA_1LC1RD_0RB0LC_0LA1RA : srun tm true true cho_1RB1RA_1LC1RD_0RB0LC_0LA1RA B0_1RB1RA_1LC1RD_0RB0LC_0LA1RA = Some (B1_1RB1RA_1LC1RD_0RB0LC_0LA1RA, 6, 10).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RA_1LC1RD_0RB0LC_0LA1RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_01_1 q0 ++ [S0]) [] j A0_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
Proof.
  intros p j q0 E. destruct (Alph_00_01_1.cview_some_Alph_00_01_1 p j q0 E) as (H1 & _).
  unfold Cc_1RB1RA_1LC1RD_0RB0LC_0LA1RA, cden, A0_1RB1RA_1LC1RD_0RB0LC_0LA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1RA_1LC1RD_0RB0LC_0LA1RA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_00_01_1 q0 ++ [S0]) [] j A1_1RB1RA_1LC1RD_0RB0LC_0LA1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_00_01_1.cview_some_Alph_00_01_1 p j q0 E) as (_ & H2).
  unfold Cc_1RB1RA_1LC1RD_0RB0LC_0LA1RA, cden, A1_1RB1RA_1LC1RD_0RB0LC_0LA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RA_1LC1RD_0RB0LC_0LA1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (6 * j + 10), (cden (Ap_Alph_00_01_1 q0 ++ [S0]) [] j A1_1RB1RA_1LC1RD_0RB0LC_0LA1RA).
  split; [lia|]. split; [| exact (gei_1RB1RA_1LC1RD_0RB0LC_0LA1RA p j q0 E)].
  rewrite (gsi_1RB1RA_1LC1RD_0RB0LC_0LA1RA p j q0 E).
  exact (srun_sound tm false true chi_1RB1RA_1LC1RD_0RB0LC_0LA1RA A0_1RB1RA_1LC1RD_0RB0LC_0LA1RA A1_1RB1RA_1LC1RD_0RB0LC_0LA1RA 6 10
           run_int_1RB1RA_1LC1RD_0RB0LC_0LA1RA (Ap_Alph_00_01_1 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1RA_1LC1RD_0RB0LC_0LA1RA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
Proof.
  intros p j E. destruct (Alph_00_01_1.cview_none_Alph_00_01_1 p j E) as (H1 & _).
  unfold Cc_1RB1RA_1LC1RD_0RB0LC_0LA1RA, cden, B0_1RB1RA_1LC1RD_0RB0LC_0LA1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RA_1LC1RD_0RB0LC_0LA1RA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RA_1LC1RD_0RB0LC_0LA1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RA_1LC1RD_0RB0LC_0LA1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_00_01_1.cview_none_Alph_00_01_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RA_1LC1RD_0RB0LC_0LA1RA
             = (StB, (rep [S0;S0] (S j) ++ [S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB1RA_1LC1RD_0RB0LC_0LA1RA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1RA_1LC1RD_0RB0LC_0LA1RA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB1RA_1LC1RD_0RB0LC_0LA1RA. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1RA_1LC1RD_0RB0LC_0LA1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RA_1LC1RD_0RB0LC_0LA1RA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RA_1LC1RD_0RB0LC_0LA1RA B0_1RB1RA_1LC1RD_0RB0LC_0LA1RA B1_1RB1RA_1LC1RD_0RB0LC_0LA1RA 6 10 p j' [] []).
    + exact run_ovf_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RA_1LC1RD_0RB0LC_0LA1RA p j' E).
    + exact (geo_1RB1RA_1LC1RD_0RB0LC_0LA1RA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RA_1LC1RD_0RB0LC_0LA1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 4.
  assert (H : match csteps tm 4 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RA_1LC1RD_0RB0LC_0LA1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RA_1LC1RD_0RB0LC_0LA1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RA_1LC1RD_0RB0LC_0LA1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RA_1LC1RD_0RB0LC_0LA1RA p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB1RA_1LC1RD_0RB0LC_0LA1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1RA_1LC1RD_0RB0LC_0LA1RA = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB1RA_1LC1RD_0RB0LC_0LA1RA p j (Ap_Alph_00_01_1 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1RA_1LC1RD_0RB0LC_0LA1RA p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RA_1LC1RD_0RB0LC_0LA1RA : forall t, ~ In t pins_1RB1RA_1LC1RD_0RB0LC_0LA1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RA_1LC1RD_0RB0LC_0LA1RA [SWinR 2; SCycL 4 0; SWin 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1RA_1LC1RD_0RB0LC_0LA1RA (StA, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1RA_1LC1RD_0RB0LC_0LA1RA [SWinR 2; SCycL 4 0; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RA_1LC1RD_0RB0LC_0LA1RA [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RA_1LC1RD_0RB0LC_0LA1RA [SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RA_1LC1RD_0RB0LC_0LA1RA [SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RA_1LC1RD_0RB0LC_0LA1RA [SWinR 2; SCycL 4 0; SWin 2; SWinL 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1RA_1LC1RD_0RB0LC_0LA1RA (StD, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1RA_1LC1RD_0RB0LC_0LA1RA [SWinR 2; SCycL 4 0; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RA_1LC1RD_0RB0LC_0LA1RA [SWinR 2; SCycL 4 0; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB1RA_1LC1RD_0RB0LC_0LA1RA : NeverQuasiHaltsTr tmm_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
Proof.
  apply (glue_neverqhtr tmm_1RB1RA_1LC1RD_0RB0LC_0LA1RA pins_1RB1RA_1LC1RD_0RB0LC_0LA1RA Cc 1).
  - exact boot_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
  - intros p _. apply lap_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
  - intros t Ht p _. apply fire_1RB1RA_1LC1RD_0RB0LC_0LA1RA. exact Ht.
Qed.

Theorem nqhtr_1RB1RA_1LC1RD_0RB0LC_0LA1RA : NeverQuasiHaltsTr tm_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
Proof. apply (neverqhtr_mirror tm_1RB1RA_1LC1RD_0RB0LC_0LA1RA). rewrite mirror_ok_1RB1RA_1LC1RD_0RB0LC_0LA1RA. exact nqhtrm_1RB1RA_1LC1RD_0RB0LC_0LA1RA. Qed.

Theorem nonhalt_1RB1RA_1LC1RD_0RB0LC_0LA1RA : NonHalt tm_1RB1RA_1LC1RD_0RB0LC_0LA1RA.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB1RA_1LC1RD_0RB0LC_0LA1RA. Qed.

End LAPT_1RB1RA_1LC1RD_0RB0LC_0LA1RA.

Module LAPT_1RB1RA_1LC1RD_0RB0LC_0LA1RD.
(** * LAPT_1RB1RA_1LC1RD_0RB0LC_0LA1RD: TRANSITION-LEVEL board for machine 1RB1RA_1LC1RD_0RB0LC_0LA1RD, boarded by CERTIFICATE.

    Auto-emitted by tools/counters/emit_lapcert.py (UNTRUSTED emitter; the Coq
    kernel re-runs the checker on every line below).  Left-growth binary
    counter under the Ap_Alph_00_01_1 digit alphabet (Alph_00_01_1.v), anchored at

      Cc p = (StB, (Ap_Alph_00_01_1 p ++ [S0], S0, []))

    The lap is DATA, not a proof script: each branch is a list of steps for
    [Checkers/LapDecider.v], run by the kernel through [vm_compute] and
    discharged by the single theorem [srun_sound].

      interior  (cview p = (j, Some q0)):  6*j+10 steps
      overflow  (cview p = (S j, None)):   6*j+12 steps

    The interior branch closes EXACTLY (which is what feeds
    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 198 anchors.
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
