(** ** The lap *)

Lemma lap_1RB1RA_1LC1RD_0RB0LC_0LA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
