    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RA_1LC1RD_0RB0LC_0LA1RD B0_1RB1RA_1LC1RD_0RB0LC_0LA1RD B1_1RB1RA_1LC1RD_0RB0LC_0LA1RD 6 12 p j' [] []).
    + exact run_ovf_1RB1RA_1LC1RD_0RB0LC_0LA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RA_1LC1RD_0RB0LC_0LA1RD p j' E).
    + exact (geo_1RB1RA_1LC1RD_0RB0LC_0LA1RD p j' E).
    + lia.
