(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RA_1LC1RD_0RB0LC_1LA0LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB1RA_1LC1RD_0RB0LC_1LA0LA p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (8 * j + 23), (cden [] [] j BB1_1RB1RA_1LC1RD_0RB0LC_1LA0LA).
      split; [lia|]. split; [| exact (gbo_1RB1RA_1LC1RD_0RB0LC_1LA0LA j)].
      rewrite (gso_1RB1RA_1LC1RD_0RB0LC_1LA0LA p j E).
      exact (srun_sound tm true true chb_1RB1RA_1LC1RD_0RB0LC_1LA0LA B0_1RB1RA_1LC1RD_0RB0LC_1LA0LA BB1_1RB1RA_1LC1RD_0RB0LC_1LA0LA 8 23
               run_boot_1RB1RA_1LC1RD_0RB0LC_1LA0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1RA_1LC1RD_0RB0LC_1LA0LA p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (8 * j + 12), (cden [] [] j BM1_1RB1RA_1LC1RD_0RB0LC_1LA0LA).
      split; [| exact (gbo2_1RB1RA_1LC1RD_0RB0LC_1LA0LA j)].
      rewrite (gxi_1RB1RA_1LC1RD_0RB0LC_1LA0LA j).
      exact (srun_sound tm true true chm_1RB1RA_1LC1RD_0RB0LC_1LA0LA BM0_1RB1RA_1LC1RD_0RB0LC_1LA0LA BM1_1RB1RA_1LC1RD_0RB0LC_1LA0LA 8 12
               run_shift_1RB1RA_1LC1RD_0RB0LC_1LA0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (8 * j + 29), (cden [] [] j B1_1RB1RA_1LC1RD_0RB0LC_1LA0LA).
    split; [| exact (geo_1RB1RA_1LC1RD_0RB0LC_1LA0LA p j E)].
    rewrite (gxi2_1RB1RA_1LC1RD_0RB0LC_1LA0LA j).
    exact (srun_sound tm true true che_1RB1RA_1LC1RD_0RB0LC_1LA0LA BE0_1RB1RA_1LC1RD_0RB0LC_1LA0LA B1_1RB1RA_1LC1RD_0RB0LC_1LA0LA 8 29
             run_exit_1RB1RA_1LC1RD_0RB0LC_1LA0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1RA_1LC1RD_0RB0LC_1LA0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RA_1LC1RD_0RB0LC_1LA0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1RA_1LC1RD_0RB0LC_1LA0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RA_1LC1RD_0RB0LC_1LA0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 35.
  assert (H : match csteps tm 35 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 35 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RA_1LC1RD_0RB0LC_1LA0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RA_1LC1RD_0RB0LC_1LA0LA = Some t ->
  forall p j, cview p = (S j, None) ->
