  apply (fire_of_run_instr tm Cc true true l B0_1RB1RA_1LC1RD_0RB0LC_1LA0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RA_1LC1RD_0RB0LC_1LA0LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RA_1LC1RD_0RB0LC_1LA0LA : forall t, ~ In t pins_1RB1RA_1LC1RD_0RB0LC_1LA0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
