(** ** Bootstrap *)

Lemma boot_1RB1RA_1LC1RD_0RB0LC_1LA1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 33.
  assert (H : match csteps tm 33 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
