(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RA_1LC1RD_0RB0LC_1RA1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_000_001_1 q0 ++ [S0]) [] j A0_1RB1RA_1LC1RD_0RB0LC_1RA1LD.
