  - destruct (lapi_1RB1RA_1LC1RD_0RB0LC_1RA1LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RA_1LC1RD_0RB0LC_1RA1LD B0_1RB1RA_1LC1RD_0RB0LC_1RA1LD B1_1RB1RA_1LC1RD_0RB0LC_1RA1LD 12 15 p j' [] []).
    + exact run_ovf_1RB1RA_1LC1RD_0RB0LC_1RA1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RA_1LC1RD_0RB0LC_1RA1LD p j' E).
    + exact (geo_1RB1RA_1LC1RD_0RB0LC_1RA1LD p j' E).
    + lia.
