Definition BM0_1RB1RA_1LC1RD_0RD0LC_1RA1RB : sconf := mkC StC (mkS [] [S0;S0;S1] 1 0 [S0;S0;S0;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition BM1_1RB1RA_1LC1RD_0RD0LC_1RA1RB : sconf := mkC StC (mkS [] [S0;S0;S0] 1 0 [S0;S0;S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition chm_1RB1RA_1LC1RD_0RD0LC_1RA1RB : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_shift_1RB1RA_1LC1RD_0RD0LC_1RA1RB : srun tm true true chm_1RB1RA_1LC1RD_0RD0LC_1RA1RB BM0_1RB1RA_1LC1RD_0RD0LC_1RA1RB = Some (BM1_1RB1RA_1LC1RD_0RD0LC_1RA1RB, 6, 6).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RA_1LC1RD_0RD0LC_1RA1RB : sconf := mkC StC (mkS [] [S0;S0;S1] 1 0 [S0;S0;S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1RA_1LC1RD_0RD0LC_1RA1RB : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 8; SCycR 3; SWin 2; SRotL 1; SWin 1; SRotL 1; SWin 1; SRotL 3; SFoldL 1].

Lemma run_exit_1RB1RA_1LC1RD_0RD0LC_1RA1RB : srun tm true true che_1RB1RA_1LC1RD_0RD0LC_1RA1RB BE0_1RB1RA_1LC1RD_0RD0LC_1RA1RB = Some (B1_1RB1RA_1LC1RD_0RD0LC_1RA1RB, 6, 17).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RA_1LC1RD_0RD0LC_1RA1RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_000_001_1 q0 ++ [S0]) [] j A0_1RB1RA_1LC1RD_0RD0LC_1RA1RB.
Proof.
  intros p j q0 E. destruct (Alph_000_001_1.cview_some_Alph_000_001_1 p j q0 E) as (H1 & _).
  unfold Cc_1RB1RA_1LC1RD_0RD0LC_1RA1RB, cden, A0_1RB1RA_1LC1RD_0RD0LC_1RA1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S1;S0] where the anchor has [S1;S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1RA_1LC1RD_0RD0LC_1RA1RB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_000_001_1 q0 ++ [S0]) [] j A1_1RB1RA_1LC1RD_0RD0LC_1RA1RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_000_001_1.cview_some_Alph_000_001_1 p j q0 E) as (_ & H2).
  unfold Cc_1RB1RA_1LC1RD_0RD0LC_1RA1RB, cden, A1_1RB1RA_1LC1RD_0RD0LC_1RA1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S1;S0]) with (([S1;S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

