(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RA_1LC1RD_0RD0LC_1RA1RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB1RA_1LC1RD_0RD0LC_1RA1RB p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 13), (cden [] [] j BB1_1RB1RA_1LC1RD_0RD0LC_1RA1RB).
      split; [lia|]. split; [| exact (gbo_1RB1RA_1LC1RD_0RD0LC_1RA1RB j)].
      rewrite (gso_1RB1RA_1LC1RD_0RD0LC_1RA1RB p j E).
      exact (srun_sound tm true true chb_1RB1RA_1LC1RD_0RD0LC_1RA1RB B0_1RB1RA_1LC1RD_0RD0LC_1RA1RB BB1_1RB1RA_1LC1RD_0RD0LC_1RA1RB 6 13
               run_boot_1RB1RA_1LC1RD_0RD0LC_1RA1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1RA_1LC1RD_0RD0LC_1RA1RB p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (6 * j + 6), (cden [] [] j BM1_1RB1RA_1LC1RD_0RD0LC_1RA1RB).
      split; [| exact (gbo2_1RB1RA_1LC1RD_0RD0LC_1RA1RB j)].
      rewrite (gxi_1RB1RA_1LC1RD_0RD0LC_1RA1RB j).
      exact (srun_sound tm true true chm_1RB1RA_1LC1RD_0RD0LC_1RA1RB BM0_1RB1RA_1LC1RD_0RD0LC_1RA1RB BM1_1RB1RA_1LC1RD_0RD0LC_1RA1RB 6 6
               run_shift_1RB1RA_1LC1RD_0RD0LC_1RA1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (6 * j + 17), (cden [] [] j B1_1RB1RA_1LC1RD_0RD0LC_1RA1RB).
    split; [| exact (geo_1RB1RA_1LC1RD_0RD0LC_1RA1RB p j E)].
    rewrite (gxi2_1RB1RA_1LC1RD_0RD0LC_1RA1RB j).
    exact (srun_sound tm true true che_1RB1RA_1LC1RD_0RD0LC_1RA1RB BE0_1RB1RA_1LC1RD_0RD0LC_1RA1RB B1_1RB1RA_1LC1RD_0RD0LC_1RA1RB 6 17
             run_exit_1RB1RA_1LC1RD_0RD0LC_1RA1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1RA_1LC1RD_0RD0LC_1RA1RB : forall p, exists n c',
