Lemma lapil_1RB1RA_1RC0LA_1LD0LA_0RB0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1RA_1RC0LA_1LD0LA_0RB0LD p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RA_1RC0LA_1LD0LA_0RB0LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1RA_1RC0LA_1LD0LA_0RB0LD p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB1RA_1RC0LA_1LD0LA_0RB0LD).
    split; [lia|]. split; [| exact (gbo_1RB1RA_1RC0LA_1LD0LA_0RB0LD j)].
    rewrite (gso_1RB1RA_1RC0LA_1LD0LA_0RB0LD p j E).
    exact (srun_sound tm true true chb_1RB1RA_1RC0LA_1LD0LA_0RB0LD B0_1RB1RA_1RC0LA_1LD0LA_0RB0LD BB1_1RB1RA_1RC0LA_1LD0LA_0RB0LD 6 4
             run_boot_1RB1RA_1RC0LA_1LD0LA_0RB0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 14), (cden [] [] j B1_1RB1RA_1RC0LA_1LD0LA_0RB0LD).
    split; [| exact (geo_1RB1RA_1RC0LA_1LD0LA_0RB0LD p j E)].
    rewrite (gxi_1RB1RA_1RC0LA_1LD0LA_0RB0LD j).
    exact (srun_sound tm true true che_1RB1RA_1RC0LA_1LD0LA_0RB0LD BE0_1RB1RA_1RC0LA_1LD0LA_0RB0LD B1_1RB1RA_1RC0LA_1LD0LA_0RB0LD 6 14
             run_exit_1RB1RA_1RC0LA_1LD0LA_0RB0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1RA_1RC0LA_1LD0LA_0RB0LD : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1RA_1RC0LA_1LD0LA_0RB0LD = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_1RB1RA_1RC0LA_1LD0LA_0RB0LD q p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB1RA_1RC0LA_1LD0LA_0RB0LD). split;
      [| exact (gbo_1RB1RA_1RC0LA_1LD0LA_0RB0LD j)].
    rewrite (gso_1RB1RA_1RC0LA_1LD0LA_0RB0LD p j E).
    exact (srun_sound tm true true chb_1RB1RA_1RC0LA_1LD0LA_0RB0LD B0_1RB1RA_1RC0LA_1LD0LA_0RB0LD BB1_1RB1RA_1RC0LA_1LD0LA_0RB0LD 6 4
             run_boot_1RB1RA_1RC0LA_1LD0LA_0RB0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (vis_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (vis_of_run tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1RA_1RC0LA_1LD0LA_0RB0LD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1RA_1RC0LA_1LD0LA_0RB0LD j)].
Qed.



(** ** The lap *)

Lemma lap_1RB1RA_1RC0LA_1LD0LA_0RB0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RA_1RC0LA_1LD0LA_0RB0LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1RA_1RC0LA_1LD0LA_0RB0LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RA_1RC0LA_1LD0LA_0RB0LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 5.
  assert (H : match csteps tm 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RA_1RC0LA_1LD0LA_0RB0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RA_1RC0LA_1LD0LA_0RB0LD = Some t ->
