    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RA_1RC0LA_1LD0LA_0RB0LD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1RA_1RC0LA_1LD0LA_0RB0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1RA_1RC0LA_1LD0LA_0RB0LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1RA_1RC0LA_1LD0LA_0RB0LD t p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB1RA_1RC0LA_1LD0LA_0RB0LD). split;
      [| exact (gbo_1RB1RA_1RC0LA_1LD0LA_0RB0LD j)].
    rewrite (gso_1RB1RA_1RC0LA_1LD0LA_0RB0LD p j E).
    exact (srun_sound tm true true chb_1RB1RA_1RC0LA_1LD0LA_0RB0LD B0_1RB1RA_1RC0LA_1LD0LA_0RB0LD BB1_1RB1RA_1RC0LA_1LD0LA_0RB0LD 6 4
             run_boot_1RB1RA_1RC0LA_1LD0LA_0RB0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1RA_1RC0LA_1LD0LA_0RB0LD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1RA_1RC0LA_1LD0LA_0RB0LD j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RA_1RC0LA_1LD0LA_0RB0LD : forall t, ~ In t pins_1RB1RA_1RC0LA_1LD0LA_0RB0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RA_1RC0LA_1LD0LA_0RB0LD.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RA_1RC0LA_1LD0LA_0RB0LD (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1RA_1RC0LA_1LD0LA_0RB0LD [SRotL 1; SWin 1; SCycL 4 0; SWin 3] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RA_1RC0LA_1LD0LA_0RB0LD (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RA_1RC0LA_1LD0LA_0RB0LD [SRotL 1; SWin 1; SCycL 4 0; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RA_1RC0LA_1LD0LA_0RB0LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RA_1RC0LA_1LD0LA_0RB0LD (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RA_1RC0LA_1LD0LA_0RB0LD [SRotL 1; SWin 1; SCycL 4 0; SWin 4] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RA_1RC0LA_1LD0LA_0RB0LD
      with (l := [SRotL 1; SWin 1; SCycL 4 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RA_1RC0LA_1LD0LA_0RB0LD (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RA_1RC0LA_1LD0LA_0RB0LD [SRotL 1; SWin 1; SCycL 4 0; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RA_1RC0LA_1LD0LA_0RB0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RA_1RC0LA_1LD0LA_0RB0LD
      with (l := [SRotL 1; SWin 1; SCycL 4 0; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB1RA_1RC0LA_1LD0LA_0RB0LD : NeverQuasiHaltsTr tmm_1RB1RA_1RC0LA_1LD0LA_0RB0LD.
Proof.
  apply (glue_neverqhtr tmm_1RB1RA_1RC0LA_1LD0LA_0RB0LD pins_1RB1RA_1RC0LA_1LD0LA_0RB0LD Cc 1).
  - exact boot_1RB1RA_1RC0LA_1LD0LA_0RB0LD.
