Lemma gz_1RB1RA_1RC1LA_1LD1RA_0RC0LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0;S1;S0]) [] 0 Z0_1RB1RA_1RC1LA_1LD1RA_0RC0LD /\
  cden (Ap_Alph_000_100_1 q0 ++ [S0;S1;S0]) [] 0 Z1_1RB1RA_1RC1LA_1LD1RA_0RC0LD = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_000_100_1.cview_some_Alph_000_100_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RA_1RC1LA_1LD1RA_0RC0LD, cden, Z0_1RB1RA_1RC1LA_1LD1RA_0RC0LD, Z1_1RB1RA_1RC1LA_1LD1RA_0RC0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
