  unfold Cc_1RB1RA_1RC1LA_1LD1RA_0RC0LD, cden, P0_1RB1RA_1RC1LA_1LD1RA_0RC0LD, P1_1RB1RA_1RC1LA_1LD1RA_0RC0LD; cbn [c_st c_l c_h c_r].
