Lemma lapi_1RB1RA_1RC1LA_1LD1RA_0RC0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
