    rewrite (srun_sound tm false true chz_1RB1RA_1RC1LA_1LD1RA_0RC0LD Z0_1RB1RA_1RC1LA_1LD1RA_0RC0LD Z1_1RB1RA_1RC1LA_1LD1RA_0RC0LD 0 2
