    rewrite (srun_sound tm false true chp_1RB1RA_1RC1LA_1LD1RA_0RC0LD P0_1RB1RA_1RC1LA_1LD1RA_0RC0LD P1_1RB1RA_1RC1LA_1LD1RA_0RC0LD 6 8
