  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S0 DR StB | StD, S1 => mk S0 DL StD end.

(** Its mirror 1LB1LA_1LC---_1RD1RA_0LB0RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1RA_1RC____1LD1LA_0RB0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DL StC | StB, S1 => None
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S0 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RA_1RC____1LD1LA_0RB0LD : list Instr := [(StB, S1)].
Definition tmw_1RB1RA_1RC____1LD1LA_0RB0LD : TM := tm_wrap_trs tmm_1RB1RA_1RC____1LD1LA_0RB0LD pins_1RB1RA_1RC____1LD1LA_0RB0LD.
Local Notation tm := tmw_1RB1RA_1RC____1LD1LA_0RB0LD.

Lemma mirror_ok_1RB1RA_1RC____1LD1LA_0RB0LD : mirror_tm tm_1RB1RA_1RC____1LD1LA_0RB0LD = tmm_1RB1RA_1RC____1LD1LA_0RB0LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1RA_1RC____1LD1LA_0RB0LD (p : positive) : cconf := (StD, (Ap_Alph_000_010_0 p ++ [S0;S1;S0], S0, [])).
Local Notation Cc := Cc_1RB1RA_1RC____1LD1LA_0RB0LD.

(** ** The certificate *)

Definition A0_1RB1RA_1RC____1LD1LA_0RB0LD : sconf := mkC StD (mkS [] [S0;S1;S0] 1 0 [S0;S0;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1RA_1RC____1LD1LA_0RB0LD : sconf := mkC StD (mkS [] [S0;S0;S0] 1 0 [S0;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chi_1RB1RA_1RC____1LD1LA_0RB0LD : list lstep := [SRotL 1; SWin 1; SCycL 5 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_int_1RB1RA_1RC____1LD1LA_0RB0LD : srun tm false true chi_1RB1RA_1RC____1LD1LA_0RB0LD A0_1RB1RA_1RC____1LD1LA_0RB0LD = Some (A1_1RB1RA_1RC____1LD1LA_0RB0LD, 8, 4).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1RA_1RC____1LD1LA_0RB0LD : sconf := mkC StD (mkS [] [S0;S1;S0] 1 0 [S0;S0;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1RA_1RC____1LD1LA_0RB0LD : sconf := mkC StD (mkS [] [S0;S0;S0] 1 1 [S0;S0;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_000_010_0 at StD *)
Definition Cin_1RB1RA_1RC____1LD1LA_0RB0LD (v : positive) : cconf := (StD, (Ap_Alph_000_010_0 v ++ [S1;S1], S0, [])).
Local Notation Cin := Cin_1RB1RA_1RC____1LD1LA_0RB0LD.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1RA_1RC____1LD1LA_0RB0LD : forall n, Ap_Alph_000_010_0 (pow2 n) = rep [S0;S0;S0] n ++ [S0].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1RA_1RC____1LD1LA_0RB0LD : sconf := mkC StD (mkS [] [S0;S1;S0] 1 0 [S0;S0;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1RA_1RC____1LD1LA_0RB0LD : sconf := mkC StD (mkS [] [S0;S0;S0] 1 0 [S0;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chn_1RB1RA_1RC____1LD1LA_0RB0LD : list lstep := [SRotL 1; SWin 1; SCycL 5 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_inner_1RB1RA_1RC____1LD1LA_0RB0LD : srun tm false true chn_1RB1RA_1RC____1LD1LA_0RB0LD AI0_1RB1RA_1RC____1LD1LA_0RB0LD = Some (AI1_1RB1RA_1RC____1LD1LA_0RB0LD, 8, 4).
