(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1RA_1RC____1LD1LA_0RB0LD : sconf := mkC StD (mkS [] [S0;S0;S0] 1 0 [S0;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB1RA_1RC____1LD1LA_0RB0LD : list lstep := [SRotL 1; SWin 1; SCycL 5 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_boot_1RB1RA_1RC____1LD1LA_0RB0LD : srun tm true true chb_1RB1RA_1RC____1LD1LA_0RB0LD B0_1RB1RA_1RC____1LD1LA_0RB0LD = Some (BB1_1RB1RA_1RC____1LD1LA_0RB0LD, 8, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RA_1RC____1LD1LA_0RB0LD : sconf := mkC StD (mkS [] [S0;S1;S0] 1 0 [S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1RA_1RC____1LD1LA_0RB0LD : list lstep := [SRotL 1; SWin 1; SCycL 5 0; SWin 4; SWinL 8; SCycR 3; SWin 1; SRotL 2; SFoldL 1].

Lemma run_exit_1RB1RA_1RC____1LD1LA_0RB0LD : srun tm true true che_1RB1RA_1RC____1LD1LA_0RB0LD BE0_1RB1RA_1RC____1LD1LA_0RB0LD = Some (B1_1RB1RA_1RC____1LD1LA_0RB0LD, 8, 14).
