(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RB_0LB1LC_0RD0LA_1LB1RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1RB_0LB1LC_0RD0LA_1LB1RD p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB1RB_0LB1LC_0RD0LA_1LB1RD).
    split; [lia|]. split; [| exact (gbo_1RB1RB_0LB1LC_0RD0LA_1LB1RD j)].
    rewrite (gso_1RB1RB_0LB1LC_0RD0LA_1LB1RD p j E).
    exact (srun_sound tm true true chb_1RB1RB_0LB1LC_0RD0LA_1LB1RD B0_1RB1RB_0LB1LC_0RD0LA_1LB1RD BB1_1RB1RB_0LB1LC_0RD0LA_1LB1RD 6 4
             run_boot_1RB1RB_0LB1LC_0RD0LA_1LB1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 15), (cden [] [] j B1_1RB1RB_0LB1LC_0RD0LA_1LB1RD).
